public class Main {
    static void work(int n) {
        try {
            if (n < 0) throw new IllegalArgumentException();
            System.out.print("T");
        } catch (Exception e) {
            System.out.print("E");
        } catch (RuntimeException e) {
            System.out.print("R");
        } finally {
            System.out.print("F");
        }
    }
    public static void main(String[] args) {
        work(1);
    }
}

